const pruneWorkflowMatchLogs = `-- name: PruneWorkflowMatchLogs :execrows
DELETE FROM workflow_match_logs AS l WHERE l.id IN (
    SELECT o.id FROM workflow_match_logs AS o WHERE o.created_at < $1::timestamptz
    LIMIT $2::integer
)
`

type PruneWorkflowMatchLogsParams struct {
	Before   time.Time `json:"before"`
	RowLimit int32     `json:"row_limit"`
}

// PruneWorkflowMatchLogs deletes match logs older than a moment.
func (q *Queries) PruneWorkflowMatchLogs(ctx context.Context, arg PruneWorkflowMatchLogsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneWorkflowMatchLogs, arg.Before, arg.RowLimit)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const publicAuthorBefore = `-- name: PublicAuthorBefore :one
SELECT author_type FROM messages
WHERE workspace_id = $1 AND conversation_id = $2 AND type = 'message'
  AND deleted_at IS NULL AND id < $3
ORDER BY id DESC
LIMIT 1
`

type PublicAuthorBeforeParams struct {
	WorkspaceID    ids.UUID `json:"workspace_id"`
	ConversationID ids.UUID `json:"conversation_id"`
	MessageID      ids.UUID `json:"message_id"`
}

// PublicAuthorBefore names who wrote the conversation's last public
// message before the given one, so a short "yes" is read as confirming
// the agent's answer only when that answer came right before it.
func (q *Queries) PublicAuthorBefore(ctx context.Context, arg PublicAuthorBeforeParams) (string, error) {
	row := q.db.QueryRow(ctx, publicAuthorBefore, arg.WorkspaceID, arg.ConversationID, arg.MessageID)
	var author_type string
	err := row.Scan(&author_type)
	return author_type, err
}

const quietAnchors = `-- name: QuietAnchors :one
SELECT
    coalesce((
        SELECT m.id FROM messages m
        WHERE m.workspace_id = $1 AND m.conversation_id = $2 AND m.type = 'message'
          AND m.author_type IN ('member', 'agent') AND m.deleted_at IS NULL
        ORDER BY m.id DESC LIMIT 1
    ), '00000000-0000-0000-0000-000000000000'::uuid)::uuid AS last_reply_id,
    EXISTS (
        SELECT 1 FROM messages m
        WHERE m.workspace_id = $1 AND m.conversation_id = $2 AND m.type = 'message'
          AND m.author_type = 'contact' AND m.deleted_at IS NULL AND m.id > $3
    )::boolean AS customer_wrote
`

type QuietAnchorsParams struct {
	WorkspaceID    ids.UUID `json:"workspace_id"`
	ConversationID ids.UUID `json:"conversation_id"`
	AnchorID       ids.UUID `json:"anchor_id"`
}

type QuietAnchorsRow struct {
	LastReplyID   ids.UUID `json:"last_reply_id"`
	CustomerWrote bool     `json:"customer_wrote"`
}

// QuietAnchors returns what a quiet trigger checks before it fires: the
// newest public reply by a teammate or the agent, the nil id for none,
// and whether the customer wrote after the anchor message.
func (q *Queries) QuietAnchors(ctx context.Context, arg QuietAnchorsParams) (QuietAnchorsRow, error) {
	row := q.db.QueryRow(ctx, quietAnchors, arg.WorkspaceID, arg.ConversationID, arg.AnchorID)
	var i QuietAnchorsRow
	err := row.Scan(&i.LastReplyID, &i.CustomerWrote)
	return i, err
}

